(* [comment removed for export] *)
(* [comment removed for export] *)
Definition APATEXIT : Z := 0xa1b2c.       (* [comment removed for export] *)
Definition APATX : Z := 0x60d2e0.         (* [comment removed for export] *)
Definition APATX_CALLFN : Z := 0xa1bf0.   (* [comment removed for export] *)
Definition APNEED_LOCKS : Z := 0x60d523.  (* [comment removed for export] *)
Definition ACOV_HOOK : Z := 0x6f54c.      (* [comment removed for export] *)
Definition ACOV_FLAG : Z := 0x14c1a0.     (* [comment removed for export] *)
(* [comment removed for export] *)
Definition APEXIT_GUARD : Z := 0x7ff14.   (* [comment removed for export] *)
Definition APAEF_INCB : Z := 0x5ec954.    (* [comment removed for export] *)

(* [comment removed for export] *)
Definition atx_cellsA (slot f1 a1 : Z) (m : mem) : Prop :=
  rw_cells bsegs m 0x60d2e0 [C1 (Z_to_bv 8 0)]
  /\ rw_cells bsegs m 0x60d2e4 [C4 (Z_to_bv 64 0)]
  /\ rw_cells bsegs m 0x60d2e8 [C4 (Z_to_bv 64 slot)]
  /\ rw_cells bsegs m 0x60d2f0 [C8 (Z_to_bv 64 0x60d2f8)]
  /\ rw_cells bsegs m 0x60d2f8 [C8 (Z_to_bv 64 0)]
  /\ rw_cells bsegs m 0x60d300 [C8 (Z_to_bv 64 APATX_CALLFN)]
  /\ rw_cells bsegs m 0x60d400 [C8 (Z_to_bv 64 ACOV_HOOK)]
  /\ rw_cells bsegs m 0x60d308 [C8 (Z_to_bv 64 f1)]
  /\ rw_cells bsegs m 0x60d408 [C8 (Z_to_bv 64 a1)].

(* [comment removed for export] *)
Definition atx_stateA (reg : bool) (m : mem) : Prop :=
  atx_cellsA (if reg then 2 else 1) (if reg then APATX_CALLFN else 0) (if reg then APEXIT_GUARD else 0) m
  /\ rw_cells bsegs m APAEF_INCB [C1 (Z_to_bv 8 0)]
  /\ rw_cells bsegs m ACOV_FLAG [C1 (Z_to_bv 8 0)].

Definition atx_addrA (a : Z) : Prop :=
  (0x60d2e0 <= a < 0x60d2e1)%Z \/ (0x60d2e4 <= a < 0x60d2ec)%Z \/ (0x60d2f0 <= a < 0x60d310)%Z \/ (0x60d400 <= a < 0x60d410)%Z.
Definition atx_state_addrA (a : Z) : Prop := atx_addrA a \/ (0x5ec954 <= a < 0x5ec955)%Z \/ (0x14c1a0 <= a < 0x14c1a1)%Z.

Lemma atx_cellsA_agree : forall (P : Z -> Prop) m m' slot f1 a1,
  magree bsegs P m m' -> (forall a, atx_addrA a -> P a) -> atx_cellsA slot f1 a1 m -> atx_cellsA slot f1 a1 m'.
Proof.
